export function StarRating({
  label = "{{label}}",
  rating = "{{rating}}",
  accent = "{{accent}}",
  showNumber = {{showNumber}},
}) {
  const pct = { "3": "60%", "4": "80%", "5": "100%" }[rating] ?? "80%";
  return (
    <div style={{ font: "15px system-ui, sans-serif", color: "#241430", display: "flex", alignItems: "center", gap: 10 }}>
      <span style={{ fontWeight: 600 }}>{label}</span>
      <span aria-label={`${rating} out of 5 stars`} style={{ position: "relative", display: "inline-block",
        fontSize: 18, letterSpacing: 2, lineHeight: 1 }}>
        <span aria-hidden="true" style={{ color: "#24143025" }}>&#9733;&#9733;&#9733;&#9733;&#9733;</span>
        <span aria-hidden="true" style={{ position: "absolute", inset: 0, overflow: "hidden", color: accent, width: pct }}>&#9733;&#9733;&#9733;&#9733;&#9733;</span>
      </span>
      {showNumber && <span style={{ fontSize: 13, color: "#241430aa" }}>{rating}.0 out of 5</span>}
    </div>
  );
}
